134	```ts
135	/**
136	 * Everything the plugin decides, with nothing from the SDK in it.
137	 *
138	 * A key face is a function of what the plugin knows: whether it is
139	 * signed in, whether its socket is open, which runs are held, which is
140	 * pinned, and what that run last published. `reduce` moves the state on
141	 * one event at a time; the `*Face` functions read it. Keeping them pure
142	 * is what lets the twelve states a key can be in have a test each.
143	 */
144	const FLASH_MS = 3000;
145	
146	export function initial(): DeckState {
147	  return { session: "none", socket: "closed", runs: [], any: false, pinned: null, attached: null, snapshot: null, flash: null };
148	}
149	
150	export function attachedRun(state: DeckState): string | null {
151	  if (state.pinned) return state.runs.some((r) => r.id === state.pinned) ? state.pinned : null;
152	  return state.runs.length === 1 ? state.runs[0]!.id : null;
153	}
154	
155	export function reduce(state: DeckState, event: DeckEvent, now: number): DeckState {
156	  switch (event.t) {
157	    case "session":
158	      return event.state === "ok" ? { ...state, session: "ok" } : { ...initial(), session: event.state, pinned: state.pinned };
159	    case "socket":
160	      return event.state === "open" ? { ...state, socket: "open" } : { ...state, socket: event.state, runs: [], attached: null, snapshot: null };
161	    case "runs": {
162	      const next = { ...state, runs: event.runs, any: event.any };
163	      const attached = attachedRun(next);
164	      // A run that went away takes its numbers with it; a run that is
165	      // still here keeps them until the next snapshot lands.
166	      return { ...next, attached, snapshot: attached === state.attached ? state.snapshot : null };
167	    }
168	    case "pin": {
169	      const next = { ...state, pinned: event.id };
170	      const attached = attachedRun(next);
171	      return { ...next, attached, snapshot: attached === state.attached ? state.snapshot : null };
172	    }
173	    case "snapshot":
174	      return { ...state, snapshot: event.snapshot };
175	    case "drove":
176	      return { ...state, flash: { ref: event.ref, ok: event.ok, ...(event.say ? { say: event.say } : {}), until: now + FLASH_MS } };
177	    case "tick":
178	      return state.flash && state.flash.until <= now ? { ...state, flash: null } : state;
179	  }
180	}
181	
182	/** The state every key shares before any of them has something of its own to say. */
183	function common(state: DeckState): Face | null {
184	  if (state.session === "none") return { title: "Sign in", tone: "dim" };
185	  if (state.session === "expired") return { title: "Sign in again", tone: "dim" };
186	  if (state.socket !== "open") return { title: "Offline", tone: "dim" };
187	  if (state.pinned && !state.runs.some((r) => r.id === state.pinned)) return { title: "That run has ended", tone: "dim" };
188	  if (state.runs.length === 0) return state.any ? { title: "No run open", tone: "dim" } : { title: "Not synced", tone: "dim" };
189	  if (!state.attached) return { title: "Pick a run", tone: "dim" };
190	  return null;
191	}
192	
193	function flashed(state: DeckState): Face | null {
194	  if (!state.flash || state.flash.ok) return null;
195	  return { title: state.flash.say ?? "No", tone: "refuse" };
196	}
197	
198	export function nextFace(state: DeckState): Face {
199	  const c = common(state) ?? flashed(state);
200	  if (c) return c;
201	  const offer = state.snapshot?.offer;
202	  if (!offer) return { title: "Loading…", tone: "dim" };
203	  if (offer.primary) return { title: offer.primary.label, tone: "live" };
204	  return { title: offer.needsPage ?? "Nothing to press", tone: offer.needsPage ? "refuse" : "dim" };
205	}
206	
207	export function pressFace(state: DeckState, target: PressTarget): Face {
208	  const c = common(state) ?? flashed(state);
209	  if (c) return c;
210	  const offer = state.snapshot?.offer;
211	  if (!offer) return { title: "Loading…", tone: "dim" };
212	  if (target.kind === "roll") return offer.primary?.id === "roll" ? { title: offer.primary.label, tone: "live" } : { title: "Nothing to roll", tone: "dim" };
213	  if (target.kind === "move") {
214	    const m = offer.moves.find((x) => x.id === target.id);
215	    return m ? { title: m.label, tone: "live" } : { title: "Not on offer", tone: "dim" };
216	  }
217	  const p = offer.presets.find((x) => x.kind === target.preset);
218	  return p ? { title: target.value, tone: "live", when: p.label } : { title: target.value, tone: "dim", when: "Not now" };
219	}
220	
221	export function undoFace(state: DeckState): Face {
222	  const c = common(state) ?? flashed(state);
223	  if (c) return c;
224	  const undo = state.snapshot?.offer?.undo;
225	  return undo ? { title: "Undo", tone: "live", when: undo.what } : { title: "Nothing to undo", tone: "dim" };
226	}
227	
228	export function runFace(state: DeckState): Face {
229	  if (state.session !== "ok") return common(state)!;
230	  if (state.socket !== "open") return { title: "Offline", tone: "dim" };
231	  const run = state.runs.find((r) => r.id === state.attached);
232	  if (run) return { title: run.name ?? run.packTitle ?? run.id, tone: "live", ...(run.packTitle && run.name ? { when: run.packTitle } : {}) };
233	  return common(state) ?? { title: "Pick a run", tone: "dim" };
234	}
235	
236	/** The arithmetic `stream-api.md` publishes, so a key agrees with a widget to the second. */
237	function clockText(c: NonNullable<Snapshot["clocks"]>[number], at: string, now: number): string {
238	  const since = c.status === "running" ? now - Date.parse(at) : 0;
239	  const elapsed = c.elapsedMs + since;
240	  const ms = c.seconds === null ? elapsed : Math.max(0, c.seconds * 1000 - elapsed);
241	  const s = Math.floor(ms / 1000);
242	  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
243	}
244	
245	export function metricFace(state: DeckState, field: MetricField, now: number): Face {
246	  const c = common(state);
247	  if (c) return c;
248	  const snap = state.snapshot;
249	  if (!snap) return { title: "Loading…", tone: "dim" };
250	  if (field === "score") return { title: snap.score?.text ?? "—", tone: "live", when: "Score" };
251	  if (field === "unit") return { title: String(snap.unit ?? "—"), tone: "live", when: snap.words?.unit ?? "Unit" };
252	  if (field === "latest") return { title: snap.latest?.text ?? "—", tone: "live" };
253	  if (field === "leader") {
254	    const top = snap.standings?.[0];
255	    return top ? { title: top.name, tone: "live", when: `${top.points} pts` } : { title: "—", tone: "dim", when: "Leader" };
256	  }
257	  if (field === "clock") {
258	    const clock = snap.clocks?.find((x) => x.status === "running") ?? snap.clocks?.[0];
259	    return clock && snap.at ? { title: clockText(clock, snap.at, now), tone: "live", when: clock.label } : { title: "—", tone: "dim", when: "Clock" };
260	  }
261	  if ("counter" in field) {
262	    const x = snap.counters?.find((k) => k.id === field.counter);
263	    return x ? { title: String(x.value), tone: "live", when: x.label } : { title: "—", tone: "dim" };
264	  }
265	  const r = snap.resources?.find((k) => k.id === field.resource);
266	  return r ? { title: r.max === null ? String(r.value) : `${r.value}/${r.max}`, tone: "live", when: r.label } : { title: "—", tone: "dim" };
267	}
268	```
269	
270	Declare the types from the Interfaces block at the top of the file.
