### Task 6: The state machine

Everything the plugin decides, in one pure module with no SDK import. This is the task that makes the rest testable.

**Files:**

- Create: `streamdeck/src/state.ts`
- Test: `streamdeck/src/state.test.ts`

**Interfaces:**

- Consumes: the `Offer` shape from Plan A Task 5 (copy the interface; the plugin does not import from `apps/web`).
- Produces:

```ts
export type SessionState = "none" | "expired" | "ok";
export type SocketState = "closed" | "connecting" | "open";
export interface HeldRun { id: string; name?: string; packTitle?: string }
export interface Snapshot { unit?: number; words?: { unit: string }; score?: { text: string }; latest?: { text: string } | null; clocks?: Array<{ id: string; label: string; kind: "timer" | "stopwatch"; seconds: number | null; status: string; elapsedMs: number }>; standings?: Array<{ name: string; points: number; place: number }>; counters?: Array<{ id: string; label: string; value: number }>; resources?: Array<{ id: string; label: string; value: number; max: number | null }>; at?: string; offer?: Offer }
export interface DeckState {
  session: SessionState;
  socket: SocketState;
  runs: HeldRun[];
  any: boolean;
  pinned: string | null;
  attached: string | null;
  snapshot: Snapshot | null;
  flash: { ref: string; ok: boolean; say?: string; until: number } | null;
}
export type Tone = "live" | "dim" | "refuse";
export interface Face { title: string; tone: Tone; when?: string }
export function initial(): DeckState;
export function attachedRun(state: DeckState): string | null;   // pinned if held, else the only held run, else null
export function nextFace(state: DeckState): Face;
export function pressFace(state: DeckState, target: PressTarget): Face;
export function undoFace(state: DeckState): Face;
export function runFace(state: DeckState): Face;
export function metricFace(state: DeckState, field: MetricField, now: number): Face;
export type PressTarget = { kind: "roll" } | { kind: "move"; id: string } | { kind: "answer"; preset: string; value: string };
export type MetricField = "score" | "unit" | "clock" | "latest" | "leader" | { counter: string } | { resource: string };
export function reduce(state: DeckState, event: DeckEvent, now: number): DeckState;
export type DeckEvent =
  | { t: "session"; state: SessionState }
  | { t: "socket"; state: SocketState }
  | { t: "runs"; runs: HeldRun[]; any: boolean }
  | { t: "pin"; id: string | null }
  | { t: "snapshot"; snapshot: Snapshot }
  | { t: "drove"; ref: string; ok: boolean; say?: string }
  | { t: "tick" };
```

- [ ] **Step 1: Write the failing tests**

```ts
import { describe, expect, it } from "vitest";
import { initial, reduce, nextFace, runFace, undoFace, metricFace, attachedRun } from "./state.ts";

const held = (id: string, name = "Thursday") => ({ id, name, packTitle: "The Long Kiln" });
const offer = { seq: 42, primary: { id: "roll", label: "Roll the Weather", kind: "rollTable" }, moves: [], undo: { what: "A dry wind." }, needsPage: null, presets: [] };
const T = 1_000_000;

describe("what the keys say", () => {
  it("asks for a sign-in before anything else", () => {
    expect(nextFace(initial())).toEqual({ title: "Sign in", tone: "dim" });
  });
  it("is offline with a session and no socket", () => {
    const s = reduce(initial(), { t: "session", state: "ok" }, T);
    expect(nextFace(s)).toEqual({ title: "Offline", tone: "dim" });
  });
  it("tells nothing synced from nothing open", () => {
    let s = reduce(initial(), { t: "session", state: "ok" }, T);
    s = reduce(s, { t: "socket", state: "open" }, T);
    expect(nextFace(reduce(s, { t: "runs", runs: [], any: false }, T))).toEqual({ title: "Not synced", tone: "dim" });
    expect(nextFace(reduce(s, { t: "runs", runs: [], any: true }, T))).toEqual({ title: "No run open", tone: "dim" });
  });
  it("attaches to the only held run without being asked", () => {
    let s = reduce(initial(), { t: "session", state: "ok" }, T);
    s = reduce(s, { t: "socket", state: "open" }, T);
    s = reduce(s, { t: "runs", runs: [held("s1")], any: true }, T);
    expect(attachedRun(s)).toBe("s1");
    expect(runFace(s)).toEqual({ title: "Thursday", tone: "live", when: "The Long Kiln" });
  });
  it("asks to pick between two, and a pin decides", () => {
    let s = reduce(initial(), { t: "session", state: "ok" }, T);
    s = reduce(s, { t: "socket", state: "open" }, T);
    s = reduce(s, { t: "runs", runs: [held("s1"), held("s2", "Friday")], any: true }, T);
    expect(nextFace(s)).toEqual({ title: "Pick a run", tone: "dim" });
    expect(attachedRun(reduce(s, { t: "pin", id: "s2" }, T))).toBe("s2");
  });
  it("a pinned run that ended says so rather than drifting", () => {
    let s = reduce(initial(), { t: "session", state: "ok" }, T);
    s = reduce(s, { t: "socket", state: "open" }, T);
    s = reduce(s, { t: "pin", id: "s1" }, T);
    s = reduce(s, { t: "runs", runs: [held("s2", "Friday")], any: true }, T);
    expect(nextFace(s)).toEqual({ title: "That run has ended", tone: "dim" });
  });
  it("draws the offer's primary, and the reason when there is none", () => {
    let s = reduce(initial(), { t: "session", state: "ok" }, T);
    s = reduce(s, { t: "socket", state: "open" }, T);
    s = reduce(s, { t: "runs", runs: [held("s1")], any: true }, T);
    s = reduce(s, { t: "snapshot", snapshot: { offer } }, T);
    expect(nextFace(s)).toEqual({ title: "Roll the Weather", tone: "live" });
    expect(undoFace(s)).toEqual({ title: "Undo", tone: "live", when: "A dry wind." });
    const blocked = reduce(s, { t: "snapshot", snapshot: { offer: { ...offer, primary: null, needsPage: "Name the bowl on the page" } } }, T);
    expect(nextFace(blocked)).toEqual({ title: "Name the bowl on the page", tone: "refuse" });
  });
  it("flashes a refusal for three seconds, then goes back", () => {
    let s = reduce(initial(), { t: "session", state: "ok" }, T);
    s = reduce(s, { t: "socket", state: "open" }, T);
    s = reduce(s, { t: "runs", runs: [held("s1")], any: true }, T);
    s = reduce(s, { t: "snapshot", snapshot: { offer } }, T);
    s = reduce(s, { t: "drove", ref: "r1", ok: false, say: "That moved on." }, T);
    expect(nextFace(s)).toEqual({ title: "That moved on.", tone: "refuse" });
    expect(nextFace(reduce(s, { t: "tick" }, T + 3001))).toEqual({ title: "Roll the Weather", tone: "live" });
  });
  it("ticks a running clock from the snapshot's own time", () => {
    let s = reduce(initial(), { t: "session", state: "ok" }, T);
    s = reduce(s, { t: "socket", state: "open" }, T);
    s = reduce(s, { t: "runs", runs: [held("s1")], any: true }, T);
    const at = new Date(T).toISOString();
    s = reduce(s, { t: "snapshot", snapshot: { at, clocks: [{ id: "u4", label: "Day 4", kind: "timer", seconds: 600, status: "running", elapsedMs: 10_000 }] } }, T);
    expect(metricFace(s, "clock", T + 5_000)).toEqual({ title: "9:45", tone: "live", when: "Day 4" });
  });
});
