297	+    return offer.primary?.id === "roll" ? { title: offer.primary.label, tone: "live" } : { title: "Nothing to roll", tone: "dim" };
298	+  if (target.kind === "move") {
299	+    const m = offer.moves.find((x) => x.id === target.id);
300	+    return m ? { title: m.label, tone: "live" } : { title: "Not on offer", tone: "dim" };
301	+  }
302	+  const p = offer.presets.find((x) => x.kind === target.preset);
303	+  return p ? { title: target.value, tone: "live", when: p.label } : { title: target.value, tone: "dim", when: "Not now" };
304	+}
305	+
306	+export function undoFace(state: DeckState): Face {
307	+  const c = common(state) ?? flashed(state);
308	+  if (c) return c;
309	+  const undo = state.snapshot?.offer?.undo;
310	+  return undo ? { title: "Undo", tone: "live", when: undo.what } : { title: "Nothing to undo", tone: "dim" };
311	+}
312	+
313	+export function runFace(state: DeckState): Face {
314	+  if (state.session !== "ok") return common(state)!;
315	+  if (state.socket !== "open") return { title: "Offline", tone: "dim" };
316	+  const run = state.runs.find((r) => r.id === state.attached);
317	+  if (run)
318	+    return { title: run.name ?? run.packTitle ?? run.id, tone: "live", ...(run.packTitle && run.name ? { when: run.packTitle } : {}) };
319	+  return common(state) ?? { title: "Pick a run", tone: "dim" };
320	+}
321	+
322	+/** How far a clock has moved since the snapshot that reported it, in ms. */
323	+function clockElapsedMs(c: NonNullable<Snapshot["clocks"]>[number], at: string, now: number): number {
324	+  const since = c.status === "running" ? now - Date.parse(at) : 0;
325	+  return c.elapsedMs + since;
326	+}
327	+
328	+/** The arithmetic `stream-api.md` publishes, so a key agrees with a widget to the second. */
329	+function clockText(c: NonNullable<Snapshot["clocks"]>[number], at: string, now: number): string {
330	+  const elapsed = clockElapsedMs(c, at, now);
331	+  const ms = c.seconds === null ? elapsed : Math.max(0, c.seconds * 1000 - elapsed);
332	+  const s = Math.floor(ms / 1000);
333	+  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
334	+}
335	+
336	+export function metricFace(state: DeckState, field: MetricField, now: number): Face {
337	+  const c = common(state);
338	+  if (c) return c;
339	+  const snap = state.snapshot;
340	+  if (!snap) return { title: "Loading…", tone: "dim" };
341	+  if (field === "score") return { title: snap.score?.text ?? "—", tone: "live", when: "Score" };
342	+  if (field === "unit") return { title: String(snap.unit ?? "—"), tone: "live", when: snap.words?.unit ?? "Unit" };
343	+  if (field === "latest") return { title: snap.latest?.text ?? "—", tone: "live" };
344	+  if (field === "leader") {
345	+    const top = snap.standings?.[0];
346	+    return top ? { title: top.name, tone: "live", when: `${top.points} pts` } : { title: "—", tone: "dim", when: "Leader" };
347	+  }
348	+  if (field === "clock") {
349	+    const clock = snap.clocks?.find((x) => x.status === "running") ?? snap.clocks?.[0];
350	+    if (!clock || !snap.at) return { title: "—", tone: "dim", when: "Clock" };
351	+    const running = clock.kind === "timer" && clock.status === "running" && clock.seconds !== null;
352	+    const fraction = running ? clockElapsedMs(clock, snap.at, now) / (clock.seconds! * 1000) : undefined;
353	+    return { title: clockText(clock, snap.at, now), tone: "live", when: clock.label, ...(fraction !== undefined ? { fraction } : {}) };
354	+  }
355	+  if ("counter" in field) {
356	+    const x = snap.counters?.find((k) => k.id === field.counter);
357	+    return x ? { title: String(x.value), tone: "live", when: x.label } : { title: "—", tone: "dim" };
358	+  }
